import { HugeiconsIcon } from "@hugeicons/react";
import ItalicIcon from "@hugeicons/core-free-icons/ItalicIcon";

import { Toggle } from "@/registry/erbium/ui/toggle";

export default function ToggleOutline() {
  return (
    <Toggle variant="outline" aria-label="Toggle italic">
      <HugeiconsIcon icon={ItalicIcon} />
    </Toggle>
  );
}

import ExampleToggleOutline from "../examples/toggle-outline";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleToggleOutline />
  </div>
);

export default Example;
